import{_ as r,C as a,o as i,c as l,j as n,a as d,E as o,a2 as s}from"./chunks/framework.BxGh02fV.js";const b=JSON.parse('{"title":"Profile and preferences","description":"","frontmatter":{"title":"Profile and preferences"},"headers":[],"relativePath":"en/guide/preferences.md","filePath":"en/guide/preferences.md"}'),g={name:"en/guide/preferences.md"};function h(p,e,c,u,f,m){const t=a("Capture");return i(),l("div",null,[e[0]||(e[0]=n("h1",{id:"profile-and-preferences",tabindex:"-1"},[d("Profile and preferences "),n("a",{class:"header-anchor",href:"#profile-and-preferences","aria-label":'Permalink to "Profile and preferences"'},"​")],-1)),e[1]||(e[1]=n("p",null,"Preferences gather everything that applies to the whole application, whichever project is open: your identity, theme, language, connections to AI assistants, updates. Open them with ⌘ , (Ctrl+, on Windows and Linux) or by clicking your name at the top right of the window. To leave them, click a tab or the grid icon.",-1)),o(t,{name:"profil",alt:"Preferences, Identity tab: name, email and default author"}),e[2]||(e[2]=s('<h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p>On the left, a rail of categories under the <strong>Preferences</strong> title and an <strong>Applies to the whole application</strong> badge. On the right, the content of the chosen category. The categories, top to bottom: <strong>Identity</strong>, <strong>Appearance</strong>, <strong>LLM routing</strong>, <strong>MCP &amp; Skills</strong>, <strong>Stack model</strong>, <strong>Standards</strong>, <strong>Updates</strong> and <strong>Getting started</strong>.</p><h2 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;Identity&quot;">​</a></h2><p>This is a local identity, with no account. It signs your decisions, specs and commits.</p><ul><li><strong>Change photo</strong>: pick an avatar image; <strong>Remove</strong> deletes it.</li><li><strong>Name</strong> (required), <strong>Email</strong> (checked when filled in) and <strong>Default author</strong> (required): the signature of your work.</li><li><strong>Save</strong> confirms everything; the screen confirms &quot;Changes saved&quot;.</li></ul><h2 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h2>',6)),o(t,{name:"preferences",alt:"Preferences, Appearance tab: theme and language"}),e[3]||(e[3]=s('<ul><li><strong>Theme</strong>: <strong>Light</strong>, <strong>Dark</strong> or <strong>System</strong> (follows your computer&#39;s theme).</li><li><strong>Reading comfort</strong>: <strong>Compact</strong>, <strong>Standard</strong> or <strong>Comfortable</strong> — the size of elements and the density of the interface, together.</li><li><strong>Language</strong>: a drop-down list — <strong>Français</strong>, <strong>English</strong>, <strong>Español</strong> or <strong>Русский</strong>.</li></ul><p>The change applies immediately. Theme and comfort can also be set from the top bar, without opening preferences: the sun/moon button switches between light and dark, and the <strong>Aa</strong> menu picks the reading comfort.</p><h3 id="tile-palettes" tabindex="-1">Tile palettes <a class="header-anchor" href="#tile-palettes" aria-label="Permalink to &quot;Tile palettes&quot;">​</a></h3><p>The <strong>Tile palettes</strong> card lists the four provided palettes and your own. <strong>Duplicate</strong> copies a palette into a personal one; you choose its five colours and its name (Enter confirms), <strong>Delete</strong> removes it, <strong>New palette</strong> creates one. Your palettes apply to all your projects.</p>',4)),o(t,{name:"preferences-palettes",alt:"The Tile palettes card: four provided palettes and a personal one"}),e[4]||(e[4]=s('<h2 id="llm-routing" tabindex="-1">LLM routing <a class="header-anchor" href="#llm-routing" aria-label="Permalink to &quot;LLM routing&quot;">​</a></h2><p>The global routing profile: a <strong>Matrix</strong> that pairs a model and an effort with each tier, plus a fallback model. <strong>Save</strong> keeps the profile; <strong>Save as preset</strong> turns it into a named preset. The <strong>Presets</strong> list shows the base presets and your own; <strong>Apply</strong> loads one (it still has to be saved). With no profile, the screen suggests applying a base preset and then saving.</p><p>It is a suggestion: Effortless calls no agent, the agent consults this profile.</p><h2 id="mcp-skills" tabindex="-1">MCP &amp; Skills <a class="header-anchor" href="#mcp-skills" aria-label="Permalink to &quot;MCP &amp; Skills&quot;">​</a></h2><p>Installs the Effortless server and its skills into your AI assistants in one move.</p><ul><li>A status card says whether the Effortless <strong>Binary</strong> is <strong>resolved</strong> or <strong>not found</strong>, and how many clients have Effortless registered.</li><li>The list of assistants, under <strong>Applications</strong>, shows for each one whether it is <strong>Detected</strong> on your machine and its state: <strong>Ready</strong>, <strong>Partial</strong> or <strong>Nothing configured</strong>.</li><li>Select the assistants (<strong>Select detected</strong> ticks the detected ones), then <strong>Deploy</strong> or <strong>Uninstall</strong>. A recap counts what was created, updated, left unchanged or in error. <strong>Refresh status</strong> rereads the state.</li><li>The <strong>Server</strong> section holds the <strong>Command</strong> (the path to the executable; &quot;Executable not found.&quot; when the app could not locate itself) and the <strong>Grant permissions (zero-prompt)</strong> box. Under <strong>Advanced</strong>: the <strong>Arguments</strong>, the <strong>Environment</strong> and the <strong>Exposed tools</strong>.</li></ul><h2 id="stack-model" tabindex="-1">Stack model <a class="header-anchor" href="#stack-model" aria-label="Permalink to &quot;Stack model&quot;">​</a></h2><p>Pick a model in <strong>Available models</strong> (the <strong>Project</strong> badge marks a model specific to the project). Its detail shows its build and cycle. Fill in the <strong>Stack identifier</strong>, the <strong>Norm source</strong> (<strong>Embedded (default)</strong> or <strong>Shared repo (git)</strong>) and the required <strong>Variables</strong>, then <strong>Create the stack</strong>.</p><h2 id="standards" tabindex="-1">Standards <a class="header-anchor" href="#standards" aria-label="Permalink to &quot;Standards&quot;">​</a></h2><p>The <strong>Repository address</strong> of a development-standards repository shared by all your projects (local folder or git URL; empty to remove it) and, optionally, the <strong>Branch or tag (git)</strong>. <strong>Save</strong> keeps the source. <strong>Update all projects</strong> syncs them and gives the result (&quot;2 project(s) updated, 0 failed&quot;, for instance).</p><p>Syncing also happens on its own when the app starts and when a project opens; a notification announces it when standards changed. A project&#39;s local standard is never modified.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2>',12)),o(t,{name:"preferences-mises-a-jour",alt:"Preferences, Updates category: channel, current version, check and options"}),e[5]||(e[5]=s('<ul><li>Choose a <strong>Channel</strong>. A <strong>Private</strong> channel may require <code>gh</code> authentication; the screen says why it is unavailable.</li><li>The <strong>Current version</strong> is shown. <strong>Check for updates</strong> says &quot;You&#39;re up to date&quot; or &quot;Update available:&quot; with the version, its <strong>What&#39;s new</strong>, and the <strong>Update to …</strong> button.</li><li>Before installing, Effortless must stop the running MCP sessions: a &quot;Sessions to stop before updating&quot; window lists them, and <strong>Stop everything and update</strong> starts the installation. Progress is shown (download, signature check, installation, restart).</li></ul><p>Two options:</p><ul><li><strong>Check for updates on launch</strong>: at every startup, Effortless checks the channel and, when a version is available, announces it with a notification. Nothing installs without your action: installing happens here. The panel also checks when it opens.</li><li><strong>Don&#39;t ask before stopping sessions</strong>: the confirmation window no longer shows.</li></ul><p>If an older installation is detected, a &quot;Legacy installation detected&quot; banner offers <strong>Migrate to the compiled version</strong>.</p><h2 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h2><p><strong>Replay the introduction</strong> replays the first launch (identity, deployment, workspace): see <a href="/Effortless/en/guide/first-run.html">First launch</a>.</p><h2 id="with-an-ai-agent" tabindex="-1">With an AI agent <a class="header-anchor" href="#with-an-ai-agent" aria-label="Permalink to &quot;With an AI agent&quot;">​</a></h2><p>The MCP &amp; Skills deployment exists precisely to connect the app to your agents. On the agent side, <code>effortless_deploy</code> does the same job, and <code>effortless_ndd_source</code> reads or sets the standards source.</p><p>For Claude Code, the deployment also installs the Effortless <strong>status line</strong> (<code>~/.claude/effortless/statusline.mjs</code>): folder, model, branch, share of context used — read from the model&#39;s real window size —, 5-hour and 7-day quotas, then, inside an Effortless project, the phase, the mode and the active story. If you already have your own status line, it is kept: the deployment report gives the line to set to adopt Effortless&#39;s.</p>',9))])}const w=r(g,[["render",h]]);export{b as __pageData,w as default};
